30	// helpAdvertisedCommands extracts the command names `pose help` lists. Entries
31	// appear either one per line with a trailing description or grouped on a single
32	// line separated by pipes.
33	func helpAdvertisedCommands(help string) []string {
34		seen := map[string]bool{}
35		for _, line := range strings.Split(help, "\n") {
36			// A command starts at the margin of its group; a line indented further is the
37			// continuation of the description above it.
38			if !strings.HasPrefix(line, "  ") || strings.HasPrefix(line, "      ") || strings.HasPrefix(strings.TrimSpace(line), "-") {
39				continue
40			}
41			entry := strings.TrimSpace(line)
42			// Drop the description: it starts at the first run of two or more
43			// spaces after the command form.
44			if idx := strings.Index(entry, "  "); idx > 0 {
45				entry = entry[:idx]
46			}
47			// Placeholders can themselves contain pipes (`<plan|prepare|...>`),
48			// so remove them before splitting alternatives.
49			entry = commandBracketRE.ReplaceAllString(entry, " ")
50			for _, alternative := range strings.Split(entry, "|") {
51				fields := strings.Fields(alternative)
52				if len(fields) == 0 {
53					continue
54				}
55				if name := fields[0]; commandTokenRE.MatchString(name) {
56					seen[name] = true
57				}
58			}
59		}
60		names := make([]string, 0, len(seen))
61		for name := range seen {
62			names = append(names, name)
63		}
64		sort.Strings(names)
65		return names
66	}
